"""R65's fixed optimizer settings and official parameter-mode transitions."""

import math

import torch

from .r65_official_schedulefree import AdamWScheduleFree


BASE_LR, WARMUP_UPDATES = 3e-4, 720
COMMON = dict(lr=BASE_LR, betas=(.9, .999), eps=1e-8, weight_decay=1e-4, foreach=False)
ARM_CONFIGS = {
    'A': dict(implementation='torch.optim.AdamW', **COMMON,
              external_warmup_updates=WARMUP_UPDATES, deployment_parameters='ordinary'),
    'B': dict(implementation='official AdamWScheduleFree', **COMMON,
              warmup_steps=WARMUP_UPDATES, r=0., weight_lr_power=2., inner_momentum=0.,
              external_warmup_updates=0, gradient_parameters='y', deployment_parameters='averaged x'),
}


def make_optimizer(model, arm):
    if arm == 'A':
        return torch.optim.AdamW(model.parameters(), **COMMON)
    if arm == 'B':
        return AdamWScheduleFree(model.parameters(), **COMMON, warmup_steps=WARMUP_UPDATES,
                                 r=0., weight_lr_power=2., inner_momentum=0.)
    raise ValueError('Unknown R65 arm')


def training_mode(model, optimizer, arm):
    if arm == 'B':
        optimizer.train()
    model.train()


def evaluation_mode(model, optimizer, arm):
    if arm == 'B':
        optimizer.eval()
    model.eval()


def configure_update_lr(optimizer, arm, successful):
    effective = BASE_LR * min((successful+1)/WARMUP_UPDATES, 1.)
    if arm == 'A':
        for group in optimizer.param_groups:
            group['lr'] = effective
    elif any(group['k'] != successful or group['lr'] != BASE_LR or not group['train_mode']
             for group in optimizer.param_groups):
        raise ValueError('Schedule-free must train at y with its internal warmup and constant base LR')
    return effective


def observed_lr(optimizer, arm, expected):
    values = [group['scheduled_lr'] if arm == 'B' else group['lr'] for group in optimizer.param_groups]
    if any(not math.isclose(value, expected, rel_tol=1e-12, abs_tol=0.) for value in values):
        raise ValueError('The optimizers must use the same effective successful-update LR')
    return float(values[0])

def make_r45_model(params, bundle=None, state_dict=None):
    """The old path is unchanged; checkpoint reconstruction never needs the API."""
    mode = params.get('solver_representation', 'handcrafted')
    if mode not in ('handcrafted', 'code', 'shuffled_code') or params.get('pair_mode') != 'score_difference':
        raise ValueError('R45 uses R43A score_difference with handcrafted/code/shuffled_code')
    model = ScoreDifferenceSelector(**params)
    if mode != 'handcrafted':
        components = None
        if state_dict is not None:
            vectors = state_dict['solver_encoder.code_vectors'].cpu()
            mask = state_dict['solver_encoder.role_mask'].cpu()
            rows = state_dict['solver_encoder.semantic_rows'].cpu()
            if 'solver_encoder.chunk_vectors' in state_dict:
                components = {name: state_dict['solver_encoder.' + name].cpu()
                              for name in ('chunk_vectors', 'chunk_indices')}
            if not torch.equal(state_dict['solver_encoder.solver_identity'].cpu(), identity_digest()):
                raise ValueError('Checkpoint solver identities do not match the current registry')
        else:
            from .solver_code_embeddings import validate_bundle
            validate_bundle(bundle)
            vectors, mask = bundle['vectors'], bundle['role_mask']
            if 'chunk_vectors' in bundle:
                components = {name: bundle[name] for name in ('chunk_vectors', 'chunk_indices')}
            rows = derangement(seed=params.get('permutation_seed', 4502)) if mode == 'shuffled_code' else torch.arange(M_GLOBAL)
        expected = derangement(seed=params.get('permutation_seed', 4502)) if mode == 'shuffled_code' else torch.arange(M_GLOBAL)
        if not torch.equal(rows, expected):
            raise ValueError('Code mapping differs from the declared experimental arm')
        # The common R43A modules are constructed first, with exactly the old RNG consumption.
        # Initialize the replacement branch independently, then explicitly retain common ID/LN.
        previous = model.solver_encoder
        with torch.random.fork_rng(devices=[]):
            torch.manual_seed(params.get('code_init_seed', 450002))
            model.solver_encoder = SolverCodeEncoder(vectors, mask, rows, components=components, **params)
        model.solver_encoder.solver_emb.load_state_dict(previous.solver_emb.state_dict())
        model.solver_encoder.norm.load_state_dict(previous.norm.state_dict())
    if state_dict is not None:
        model.load_state_dict(state_dict, strict=True)
    return model

def batch_protocol(batch_size):
    if not 1 <= batch_size <= 10000:
        raise ValueError('Per-task batch must retain real original TRAIN rows')
    cycles = math.ceil(10000 / batch_size)
    tail = 10000 - batch_size * (cycles-1)
    return dict(batch_size=batch_size, effective_batch_size=3*batch_size,
                final_effective_batch_size=3*tail, tail_per_task=tail,
                cycles_per_epoch=cycles, updates_per_epoch=6*cycles,
                warmup_updates=3*6*cycles, maximum_updates_per_arm=40*6*cycles)


def paired_triples(sizes, epochs=40, seed=2, batch_size=256):
    if len(sizes) != 18 or set(sizes.values()) != {10000}:
        raise ValueError('R64 requires exactly 18 original 10000-row TRAIN tasks')
    batch = batch_protocol(batch_size)
    schedule = paired_schedule(sizes, epochs, batch_size=batch_size, seed=seed)
    cycles, triples = [], []
    for order in schedule['orders']:
        epoch_cycles = [order[i:i+18] for i in range(0, len(order), 18)]
        if len(epoch_cycles) != batch['cycles_per_epoch'] or any(len(c) != 18 or set(c) != set(sizes) for c in epoch_cycles):
            raise ValueError('The existing paired schedule must really shuffle all18 once per cycle')
        cycles.append(epoch_cycles)
        triples.append([cycle[i:i+3] for cycle in epoch_cycles for i in range(0, 18, 3)])
        if len(triples[-1]) != batch['updates_per_epoch']:
            raise ValueError('R64 requires exactly six triples in each complete all18-task cycle')
    return dict(permutations=schedule['permutations'], cycles=cycles, triples=triples,
                **batch)


def triple_indices(schedule, epoch, step):
    cycle, batch_size = step // 6, schedule['batch_size']
    return [(task, schedule['permutations'][epoch][task][cycle*batch_size:cycle*batch_size+batch_size])
            for task in schedule['triples'][epoch][step]]


def prefer_checkpoint(candidate, previous):
    count = candidate['native_correct']
    if type(count) is not int or not 0 <= count <= candidate['native_total']:
        raise ValueError('Validation checkpoint selection requires integer native correct counts')
    return previous is None or count > previous['native_correct']


def dropout_seed(successful):
    return 500000003 + 2 * 100003 + successful

class GeometryResidual(nn.Module):
    def __init__(self, embedding_dim, mode="real"):
        super().__init__()
        if mode not in ("real", "zero"):
            raise ValueError("Geometry mode must be real or zero")
        self.mode = mode
        self.register_buffer("mean", torch.zeros(len(FIELDS)))
        self.register_buffer("std", torch.ones(len(FIELDS)))
        self.projection = nn.Sequential(nn.Linear(21, 64), nn.GELU(), nn.Linear(64, embedding_dim))
        nn.init.zeros_(self.projection[-1].weight)
        nn.init.zeros_(self.projection[-1].bias)

    def forward(self, node, mask, n, geometry=None):
        if geometry is None:
            geometry = local_geometry(node[..., :2], mask).float()
        geometry = (geometry.float() - self.mean) / self.std
        if self.mode == "zero":
            geometry = torch.zeros_like(geometry)
        geometry = geometry.masked_fill(~mask[..., None], 0)
        size = n.float().log1p()[:, None, None].expand(-1, node.size(1), 1) / 6.0
        return self.projection(torch.cat([node, size, geometry], -1)).masked_fill(~mask[..., None], 0)
